export const physicsDetails8L={};
const D=(id,definition,plain,method,worked,sections)=>{physicsDetails8L[id]={definition,plain,method,worked,sections:sections.map(([title,body])=>({title,body}))};};
D('p7-1','力是物体对物体的作用。力可以改变物体的形状，也可以改变物体的运动状态。力的大小、方向和作用点合称力的三要素；力的单位是牛顿，简称牛，符号N。所谓运动状态改变，既包括速度大小的改变，也包括运动方向的改变。','把“力”想成一段有来有往的关系：手推小车，手是施力物体，小车是受力物体。不能只说“这里有一个力”却找不到作用双方。捏橡皮泥主要让形状改变；踢正在滚动的球可以让它加速、减速或转弯。有些形变肉眼看不清，例如书压在桌上，桌面也有极小形变。我们可以借放大装置或传感器观察，不能因为看不见就断言没有形变。','分析力先圈定研究对象，再逐个寻找其他物体对它的作用。画示意图时先画对象，在作用点引出有箭头的线段，箭头朝力的方向，旁边标F或具体力名与大小。一个图中若比较大小，线段比例要一致。示意图重在清楚表达对象、方向和位置；不要把物体施加给外界的力混画到它自己身上。','小球沿圆弧转弯，虽然每秒走过的路程相同，速度的方向却持续变化，因此它的运动状态改变，必有力产生这种改变。另一个例子是手推墙：墙给手的力与手给墙的力同时存在，方向相反、大小相等，但它们分别作用在手和墙上，不能在手的受力图中“抵消”。',[['从开门理解三要素','推同一扇门时，保持作用点与方向相同，推得用力一些容易开门，这是大小的影响。保持力的大小与方向相同，推门把手比推门轴附近容易，这是作用点的影响。保持大小和作用点相同，沿门面朝门轴推几乎没有转动效果，而垂直门面推明显有效，这是方向的影响。实验比较应一次只改变一个因素，否则难以判断原因。'],['受力与运动不能只看表面','书静止在桌上，并不说明它不受力；支持力与重力恰好平衡。冰壶能在冰上滑很远，也不需要始终有向前的力推着，它是在惯性作用下继续运动，同时受阻力逐渐减速。回答题目时先描述速度大小和方向是否改变，再讨论力的效果，避免把“在运动”直接等同于“受向前推力”。']]);
D('p7-2','物体因发生弹性形变而产生的力叫弹力。能在外力撤去后恢复原状的形变属于弹性形变；弹力有时表现为拉力、压力或支持力。弹簧测力计利用弹簧在一定范围内伸长量随所受拉力增大而增大的规律来测量力。','把弹簧原来的长度看成起跑线。挂上物体后弹簧长了多少，才是伸长量；现在的总长度还包含原来的部分。假如原长8 cm，挂物后长11 cm，伸长量只有3 cm。桌面托住书，也可以理解为接触处微小弹性形变产生的支持力。弹性有范围，把弹簧拉得过长可能再也回不到原长，此时原来的刻度规律就不可靠了。','使用测力计先看最大可测值和一小格代表的数值，轻拉挂钩检查是否卡住，再按实际测量方向调零。测量时外力要沿弹簧轴线，物体不要碰底碰壁；稳定后正对刻度读数，记录数值与N。若水平使用而只在竖直状态调零，弹簧、挂钩自重对示数的影响可能不同，应重新检查。','某弹簧受2 N时长9 cm，受5 N时长12 cm。增加3 N使它多伸长3 cm，因此每1 N对应1 cm伸长。2 N时的2 cm伸长已经包含在9 cm中，原长是7 cm。在这个线性范围内，受4 N时长度是7+4=11 cm，绝不是把9 cm简单乘以2。',[['示数为什么不是两端拉力相加','轻质测力计水平放置，两个人分别向左右拉3 N，测力计可以静止，但弹簧仍被拉长，示数为3 N。把测力计的一端固定在墙上、另一端拉3 N，墙也给出3 N反向作用，情形完全相同。示数表示弹簧承受的张力，不表示整个测力计的合力；合力为零与内部受拉并不矛盾。'],['零误差与器材选择','若空载就显示0.2 N，之后读到2.6 N，且零误差稳定，则真实拉力约为2.4 N；最好在测量前调零。要测约4 N的力，用量程5 N、分度值0.1 N的表通常比量程50 N的表更易读准，但不得超量程。重复读数能发现偶然波动，不能自动消除一直存在的零点偏差。']]);
D('p7-3','由于地球的吸引而使物体受到的力叫重力。重力大小用G表示，质量用m表示，两者关系为G=mg。g表示每千克物体在当地所受的重力，地面附近通常约9.8 N/kg，题目也常规定取10 N/kg。重力方向竖直向下，作用可等效集中在物体的重心。','质量告诉我们有多少物质，重力告诉我们地球拉这个物体多大的力。把同一块石头带到月球，石头并没有凭空少掉物质，所以质量基本不变；月球吸引较弱，重力则减小。重力属于不需要直接接触的作用，小球离开手后依然受重力。球上升、下降或者在最高点停留一瞬，重力都不会因此变向或消失。','先把质量换成kg，再按题目给定的g求G；反求质量用m=G/g。画重力时从重心画竖直向下的箭头并标G。斜面上物体的重力仍竖直向下，沿斜面向下的是某种分解后的效果，不能用来替代重力本身。重心位置需结合质量分布；均匀规则物体可先从几何中心判断。','质量600 g的物体，取g=10 N/kg：先得m=0.6 kg，再求G=6 N。若把它放到倾斜桌面，G仍为6 N；改变的是支持和摩擦的情况。若运到g=2 N/kg的另一星体，质量仍0.6 kg，重力变为1.2 N。这里不能把6 N当成6 kg代入。',[['重心不一定在材料内部','均匀圆环的重心在圆心，圆心处可能是空的，这说明重心是把重力效果集中表达的位置，并不是藏着一颗特殊颗粒。对于不规则薄板，可以从两处分别悬挂并画出铅垂线，两条竖直线的交点就是重心附近。实验时薄板需要自由静止，铅垂线不能被手或桌面阻挡。'],['重力与稳定性','物体是否容易翻倒，与重心位置及支撑范围有关。重心的竖直投影仍在支撑区域内，通常较容易保持稳定；身体前倾过度使投影越过脚的支撑范围，就可能失去平衡。运输高大物体时降低重心、扩大底座是常见做法。分析这类现象不要把“重心低”误写为“重力小”，同一物体改变摆放姿态时质量和重力通常不变。']]);
D('p8-1','牛顿第一定律表述为：一切物体在没有受到力的作用时，总保持静止状态或匀速直线运动状态。物体保持原来运动状态不变的性质叫惯性，一切物体都有惯性。力是改变物体运动状态的原因，运动本身不需要一直有力来维持。','日常经验中推车要不停用力，是因为地面摩擦等阻力不断使车减速；并非车天生需要推力才能运动。让小车在越来越光滑的水平面上滑行，它减速越来越慢、滑行越来越远。沿着这种规律合理推理，若阻力完全为零，小车不会自行慢下来。这种理想情况难以直接实现，但能用来理解真实运动。','小车实验先让同一小车从同一斜面同一高度静止释放，使它到水平面时初速度相同，再改变水平面的粗糙程度，比较停止距离。结论不能写成“光滑面给车更大动力”，应写“阻力更小，运动状态改变得更慢”。解释惯性现象采用三个步骤：原来怎样运动、哪部分先受力改变、哪部分因惯性仍保持原状态。','汽车刹车时，车和脚先因制动力而减速，上身有保持原来向前运动的趋势，所以向前倾。系安全带可以使上身受到适当约束。这里不能写“人受到惯性向前的力”，惯性是一种性质。质量相同的汽车无论快慢，惯性相同；速度越高却需要更多能量耗散和更长制动距离。',[['没有力时保持的是哪一个状态','题目说“所有力突然消失”，应该截取那一瞬间的速度。球正在上升，就沿当时方向匀速上升；物体正在向右运动，就继续向右匀速直线运动；原来静止，就继续静止。不能因为以前受过向下重力，就认为之后仍向下转弯，也不能认为失去拉力就必然停止。'],['实验事实与科学推理的界线','实际桌面再光滑也有阻力，空气也会影响运动，因此课堂并不是直接观察到永远不停止的小车。我们观察到的是阻力逐渐减小时运动距离增加，再在合理理想条件下推得定律。答实验题时把“实验观察”“趋势”“理想推理”分开说，会比只背一句无摩擦结论更完整，也能看出控制初速度为什么重要。']]);
D('p8-2','物体保持静止或匀速直线运动的状态叫平衡状态。作用在同一物体上的两个力若大小相等、方向相反，并且沿同一直线，就能相互平衡。二力平衡可用“同体、等大、反向、共线”检查，少一个条件都不能直接认定平衡。','想象一本静止的书，地球向下拉它，桌面向上托它，这两个力作用在同一本书上，且大小相等，所以书没有加速。若书被绳子匀速向上提升，它依然可以平衡：平衡并不只表示不动，也允许方向不变、速度大小不变的运动。匀速转弯却不属于平衡，因为速度方向在变化。','第一步只选一个研究对象，第二步列其他物体对它的力，第三步根据静止或匀速直线运动列平衡关系。在竖直方向有重力、支持力和额外提力时，不能只取其中两个硬套二力平衡，而应把向上作用与向下作用分别相加。水平、竖直方向可以分开分析，但要确保没有漏力。','重40 N箱子在水平桌面，被人以10 N向上提着却仍静止。箱子受到重力40 N向下、提力10 N向上、桌面支持力N向上，因此N+10=40，N=30 N。箱子对桌面的压力也为30 N，但它不是画在箱子受力图上的力，而是作用在桌面上的力。',[['平衡力与相互作用力','书的重力与桌面对书的支持力是一对平衡力，它们都作用在书上；书压桌面与桌面支持书是一对相互作用力，分别作用于桌和书。后一对无论物体是否平衡，其大小都相等；前一对的等大则依赖书只受这两个力且处于平衡。判断时先说作用在哪个物体上，比只看等大反向更可靠。'],['如何检验四个条件','小卡片两侧用细线经滑轮悬挂相同钩码，卡片可以静止。改变一侧钩码数量，卡片移动，说明大小应相等；将卡片扭转，两力不再共线，松手后会转动，说明还需共线；把卡片剪开则两个力分作用于两部分，不再构成原对象的平衡。实验中应减小卡片重力和摩擦的干扰。']]);
D('p8-3','两个相互接触的物体发生相对滑动时，在接触面产生阻碍相对滑动的力，叫滑动摩擦力。存在相对运动趋势但仍未滑动时，也可能有静摩擦力。滑动摩擦力大小主要与压力、接触面材料和粗糙程度有关，方向阻碍接触处的相对运动。','“相对”是最关键的两个字。人在地上向前走时，脚向后蹬，有向后滑的趋势，地面对脚的摩擦反而向前。所以摩擦力不一定与物体对地运动方向相反，它也能帮助物体前进。木块在向前运动的传送带上被带快时，也可能受到向前摩擦。判断应先看接触面两者谁相对谁滑动。','测滑动摩擦力可用弹簧测力计水平匀速拉木块，此时水平拉力与摩擦平衡，示数就是摩擦大小。研究压力影响时保持接触材料、粗糙程度相同，只增加砝码；研究粗糙程度时保持总压力相同，更换接触材料。必须水平拉，斜向上拉会改变压力，还使测力计总拉力不等于水平分力。','箱子受5 N推力仍静止，水平方向无其他作用，则静摩擦力为5 N。把推力增至8 N而箱子仍未动，静摩擦变为8 N。开始滑动后，若接触条件和压力保持不变，滑动摩擦通常近似稳定，即使再增大拉力也不会立刻等量增大；此时更大的合力使物体加速。',[['压力不一定等于重力','重40 N的箱子静止在地面上，若另有向上10 N提力，地面对箱子的支持力仅30 N，箱子压地面的力也是30 N。若滑动摩擦为压力的0.2倍，摩擦应为6 N，不能用0.2×40。相反，向下按压会增大压力。先列竖直平衡关系，再研究水平摩擦，能避免套公式错用G。'],['如何评价实验结论','木块换一个底面后滑动摩擦近似相同，只能在接触材质、粗糙程度和压力基本相同的常用模型下，说它与接触面积没有明显关系。若翻面同时换成更粗糙的表面，就不能把变化归因于面积。刹车需要有益摩擦，机器转轴需要减小有害摩擦；不能把摩擦一概说成坏事。']]);
D('p8-4','如果一个力产生的作用效果与几个力共同作用的效果相同，这一个力叫这些力的合力。把几个力用合力代替，使用的是等效替代思想。同一直线上同向二力的合力大小为两力之和；反向二力的合力大小为两力之差，方向与较大的力相同。','两个人朝同一方向推同一个箱子，好比一起完成向同方向的作用；一个向右推、另一个向左推，则一部分效果互相抵消。这里的前提始终是研究同一箱子。甲拉乙、乙拉甲虽然等大反向，却分别作用在不同人身上，不能拿来计算“乙受到的合力为零”。合力是等效描述，画图时不要把它当成与原两力并存的第三个真实作用。','计算时先画方向箭头，规定向右为正，把向右力写正数、向左力写负数，再代数相加。结果正值表示向右，负值表示向左，绝对值是大小。初中同一直线二力公式不应直接用于互成夹角的力；如果两力不共线，必须使用其他方法，不能简单相加或相减。','箱子受向右12 N拉力和向左7 N摩擦力，合力为5 N向右。如果箱子此时正在向左运动，向右合力会先使它向左减速，不能说合力向右所以它已经向右。运动方向由当前速度决定，合力方向决定运动状态怎样改变，这两个方向可以暂时相反。',[['等大反向与状态保持','当同体共线的两力大小相等时，合力为零。若对象原来静止，它保持静止；若原来沿直线匀速运动，它保持原速度。反过来，已知物体匀速直线运动且水平只有拉力与摩擦力，就能推出它们等大反向。合力为零不是所有力都为零，而是作用效果在改变运动状态方面抵消。'],['反向与加倍要重新判断','同体共线5 N与3 N，方向相同合力为8 N，方向相反合力为2 N。若只把5 N方向反转，不能说合力也只是反转而大小不变，因为相加关系会变成相减关系。对于三个以上共线力，可以先把同向力各自求和，再比较两边总量；在平衡问题中求新增力，应令它与原合力等大反向。']]);
D('p9-1','压力是垂直作用在物体表面上的力。物体所受压力的大小与受力面积之比叫压强，公式p=F/S。压强反映压力作用效果的强弱，国际单位为帕斯卡，简称帕，符号Pa；1 Pa表示1 m²面积上受到1 N压力。','同一个人穿普通鞋踩雪容易陷下去，换上宽雪板便不容易下陷。人的重量没有变，区别是力量分摊到更大的面积上了。针尖、刀刃相反，通过较小接触面积让局部压力作用更明显。压力和压强并不是同一概念：大象脚对地面的压力很大，但因接触面积也大，它的压强不一定比细鞋跟更大。','计算压强分三步：先选受力面，再求垂直于这个面的压力，最后找实际接触总面积。在只有重力和支持力的水平静止物体中F=G；有向上提力、向下按力或斜面时必须重新分析。面积单位换算要平方：1 cm=0.01 m，所以1 cm²=0.0001 m²。多人或多脚同时支撑，要把实际受力面积相加。','桌子与书总重160 N，四只脚与地面总接触面积80 cm²，换成0.008 m²，压强p=160/0.008=20000 Pa。如果误把80 cm²换成0.8 m²，结果会差100倍。求桌面对地面压强时应算桌和书的总重量；求书对桌面压强时却只算书传给桌面的压力，两题的研究接触面不同。',[['比较与切割问题','均匀柱体竖直放在水平地面，p=G/S=ρgSh/S=ρgh，所以同材料柱体压强只与高度有关。竖直切去一半，重量和底面积都减半，高度不变，剩余压强不变；水平切去上半部，底面积不变而重量减半，压强减半。先判断哪几个量变了，再求比值，比记忆某种切法答案更稳妥。'],['实验怎样排除干扰','用小桌压海绵时，海绵凹陷程度表示压力效果。比较压力大小的影响，保持小桌与海绵接触面积相同，只增减桌上砝码；比较面积影响，保持总重量相同，把小桌翻转成不同接触面积。海绵材料和厚度也要一致。真实材料变形还可能受弹性等影响，因此实验结论建立在这些条件受到控制的基础上。']]);
D('p9-2','液体内部向各个方向都有压强。同种液体在同一深度的压强相等，深度越大压强越大；同一深度时，液体密度越大压强越大。液体压强公式为p=ρgh，其中h是从自由液面到研究点的竖直深度，ρ是液体密度。','水不仅压容器底部，也压侧壁，因为液体能流动。潜得越深会感到耳朵受到更明显压力，就是深度增加的表现。注意“深度”从液面向下量，而不是从杯底向上量；一个点离杯底很近，不代表它一定很深，还要看液面在哪里。公式计算的通常是液体自身造成的附加压强，如果要求包括大气的绝对压强，需再加液面上方气压。','先认液体密度、统一深度为m，用p=ρgh求压强；若求某一平面受到的均匀压力，再用F=pS。不同形状容器中，只要液体种类和底部深度相同，底部压强就相同；但底面积不同，压力仍可能不同。对于竖直侧壁，上下压强不一样，不能随便把一个深度的压强乘整个侧壁面积。','水深0.3 m、底面积0.02 m²，取ρ水=1000 kg/m³、g=10 N/kg。底部水压p=3000 Pa，水对底的压力F=60 N。若容器向上敞开得越来越宽，装水总重可能大于60 N，因为部分水重由倾斜侧壁承担；不能把所有异形容器中的底部压力都直接写成液体总重。',[['连通器为什么等高','茶壶的壶身和壶嘴上端开口、下部相通，属于连通器。装同一种液体并静止，且各液面上方气压相同时，同一水平面两侧压强必须相同，否则水还会流动，因此液面最终等高。船闸通过开启与上下游相连的通道调整闸室水位，也是利用这一思想。若两侧液面上方气压不同，等高结论不再直接成立。'],['怎样用压强计探究','把探头放入液体，U形管液面差反映探头膜受到的压强大小。研究深度时保持液体种类与探头方向相同；研究方向时把探头停在同一深度再旋转；研究密度时在不同液体的相同深度比较。U形管内液体与被测液体可能不是同一种，不能把“U形管高度差”和“探头深度”混为一个量。']]);
D('p9-3','大气对处在其中的物体产生的压强叫大气压强。大气压的产生与空气受重力且能够流动有关。标准大气压约为1.013×10⁵ Pa，可支持约760 mm高的汞柱。海拔升高时大气压通常降低；液体的沸点也随其表面气压改变。','吸管喝水时，你先让管内气压减小，杯里液面受到的外界大气压把水推入吸管。吸盘压在墙上时内部空气被挤走，外界压强大于内部，因而把吸盘压紧。我们身体平时没有被大气压压扁，是因为体内也有相应压力，许多表面两侧作用相互抵消；单看外侧很大压力会漏掉另一侧。','分析气压现象先画出两个区域，比较内外压强，再判断压力差方向。计算面积受力使用F=ΔpS时必须用压强差，而非总拿大气压单独代入。托里拆利实验使用p大气=ρ汞gh，h为汞槽自由液面与管内汞面的竖直高度差；管斜放后汞柱变长，竖直高度仍由大气压决定。','面积20 cm²吸盘内部气压2×10⁴ Pa、外界1×10⁵ Pa，净压强差8×10⁴ Pa，面积0.002 m²，因此压紧力约160 N。若只算外压会得到200 N，忽略了内侧仍然存在的40 N反向作用。实际可挂多重还受吸盘与墙间摩擦、密封稳定性等影响，不能直接把160 N当任何方向的承重极限。',[['为什么理想水柱约十米','若用水代替汞，令水柱压强等于约1×10⁵ Pa，取ρ水=1000 kg/m³、g=10 N/kg，则h=10 m。水比汞密度小得多，需要更高的水柱才能产生同样压强。这也是仅靠大气压把井水压入泵内时存在高度上限的原因；现实中还有漏气、流动损失、水汽等，实际可达高度更低。'],['常见实验误差与生活联系','托里拆利管上端进入空气，管顶便不再近似真空，内部空气也分担压强，因此测得汞柱高度偏低。把管倾斜并不会增加当地气压。高山大气压低，水可在低于100℃时沸腾，所以“水沸了”不保证温度够高；高压锅提高锅内气压使沸点升高。这里比较的是气压改变沸点，不能把所有温度变化都归因于大气压。']]);
D('p9-4','活塞式抽水机把气压差与单向阀结合，通过活塞往复运动将低处的水输送到高处。单向阀允许液体朝一个方向通过，反向时关闭。常见结构的进水阀位于筒底，另一个阀位于活塞上，两阀在上提与下压时交替开闭。','先看上提过程：活塞上移，活塞阀关闭，活塞下方体积增大、气压减小；水源液面受大气压推动，进水阀打开，水进入下腔。同时活塞上方已有的水被向上托举，从侧面出水口流出。再看下压过程：下腔水压升高，底部进水阀关闭以防回流，活塞阀打开，水通过活塞进入上方。循环往复便能连续出水。','制作先画出筒、活塞、拉杆、进水口、出水口和两个阀的位置，标清每个阀只允许向上的流向。选择容易密封的瓶筒与薄塑片，活塞与筒壁既要贴合，又要能移动。剪切打孔由成人协助或使用安全工具；不用带针注射器尖端进行危险操作。组装后先用低水位差测试，再逐渐调整行程与密封。','筒截面积6 cm²，活塞有效行程8 cm，理想每个完整循环能排48 cm³，即48 mL。25次理想共1.2 L，实测0.9 L，容积利用率为75%。这不是机械效率：这里只比较实际和理想排水体积，并没有测量输入功与有用功。用准确名称能避免把“出水比例”误写成能量效率。',[['怎么找出抽不上水的原因','第一步检查进水口是否浸在水中以及管路有无漏气；第二步看活塞是否密封、移动是否卡住；第三步分别检查阀门能否顺向开启、反向闭合。若上下运动时水总返回水源，多半是进水阀密封或方向有问题；若活塞上方水不断向下漏，活塞阀可能失效。一次只改变一个部件，再用相同循环次数比较出水量。'],['高度限制与工程改进','在当地气压约1×10⁵ Pa时，水柱约10 m产生相同压强，所以只靠大气压吸水的这类泵不能从超过该理想高度的深处直接吸起水。加长手柄可以改变手的用力，却不能增大大气压。工程上可以把泵放低、采用分级提升或其他加压方式。报告中应区分吸水高度、出口提升高度和单位时间流量，三者不是同一个性能。']]);
D('p9-5','气体和液体都具有流动性，统称流体。在适当的流动条件下，流速较大的位置压强较小，流速较小的位置压强较大。两侧压强不同会产生压力差，使纸片、液体或其他物体发生运动。应用这一规律时需要注意高度、外部加压和流动条件是否可比。','把两张纸竖直放近一些，向中间吹气，纸往往互相靠拢。中间气流变快、压强减小，外侧相对较大的压强把两纸向内推。这并不是高速空气神秘地“吸”住纸，也不是纸的重量变小了。喷雾器也类似：高速气流经过竖管上口，使那里压强较小，液面上方空气把液体推上管，再由气流吹散成雾滴。','解题先指出流速变化发生在哪一区域，再比较两侧压强，最后画出压力差造成的合力方向。若题目给平均压强差和有效面积，可算F=ΔpS。涉及飞机升力时，下表面平均压强较大、上表面较小可产生向上合力；但“空气上下两路必须同时到达尾端”不是必须满足的物理条件，不能用作解释流速差的依据。','模型机翼有效面积0.5 m²，上下平均压强差30 Pa，向上升力为15 N。若模型重10 N，且忽略其他竖直力，则净向上力为5 N，模型有向上加速趋势。升力15 N与净力5 N是不同的量：前者仅来自压强差，后者还要扣除重力。若升力恰为10 N，才可能保持竖直方向平衡。',[['生活中哪里要留意','高速列车旁空气流动复杂，局部压强变化和气流冲击可能影响人的稳定，因此应在安全线外候车。两船过近并行时，中间水流可能较快、压强偏小，外侧压力差使它们有靠近趋势。此类解释需要结合具体流场，不能把任意风中物体的运动都套成同一个原因，尤其不能忽略直接冲击等作用。'],['设计一个可重复的观察','研究吹气快慢对纸条抬起高度的影响，可固定纸的材质、长宽、夹持位置、喷口距离和方向，再改变气流强弱，记录多次高度。直接用嘴吹很难精确控制，结论应以定性为主；若加入稳定风源和流速测量，比较会更可靠。实验中不要同时换纸和吹气方向，否则即使现象不同也难以归因。']]);
D('p10-1','浸在液体中的物体会受到液体对它向上的浮力，气体对其中物体也能产生浮力。常见情况下，浮力来自物体上下表面受到的液体压力差。对于静止悬挂且不触底壁的物体，称重法可用F浮=G−F示求浮力。','把石块挂在测力计下，先在空气中读重力，再浸水，示数会减小。不是地球突然少吸引了一些石头，而是水向上托了一部分，测力计不必独自承担全部重力。石头可能仍会下沉，因为向上的浮力还小于重力。浮力与物体是否正在上升不是同一回事：下沉的石头也受浮力，漂浮的木块则有浮力与重力平衡。','用称重法先测G，再保持物体静止浸入液体，读F示，检查细线竖直、物体不触底壁、气泡已去除。若物体很轻需要向下约束，就不能把从上方悬挂的测力计生搬硬套。分析完全浸没后的深度变化时，尽管上下表面压力都增大，它们的差值仍可不变，这正是浮力通常不随深度继续增加的原因。','一个重8 N物体逐渐浸水，示数从7 N减到5 N，说明浮力从1 N增到3 N。再向下放但始终全浸没，示数仍5 N，则浮力仍3 N。若物体碰到杯底后示数变为2 N，不能据此说浮力变6 N，因为杯底还给了它向上的支持力。少画一个力就会把支持力误算为浮力。',[['压力差如何得到向上的力','设一个直立方块上下表面面积都为S，下表面比上表面深，所以向上的下表面压力大于向下的上表面压力。两者差值为浮力；侧面同深度的水平压力相互抵消。若上表面压强1000 Pa、下表面4000 Pa、面积0.002 m²，浮力是(4000−1000)×0.002=6 N。这里用压强差，不是把两压力相加。'],['探究时控制哪些条件','比较同种液体中不同浸入体积，可以固定物体和液体，逐步下放但记录是否已浸没；比较液体密度影响，则使同一物体都完全浸没再换液体。物体体积相同不代表质量相同，质量不同也不意味着浮力不同。对于软气囊下潜后被压缩的情形，体积会变化，不能再说“全浸没后浮力必不变”。']]);
D('p10-2','阿基米德原理指出：浸在液体中的物体所受浮力，大小等于它排开的液体所受重力。可写成F浮=G排=m排g=ρ液gV排。这个规律也适用于气体。排液体积是物体实际占据液体空间的体积，只有完全浸没时才等于物体外部体积。','把物体压入盛水的容器，原来占据那部分空间的水必须让位，这就是“排开”。如果容器已装到溢水口，这部分水会流出；如果尚有空位，水面可能只是升高，仍然有排水却不一定溢出。想象把被排开的水单独称重，所得重力就等于物体受到的浮力。液体越重、排开的越多，托举作用越强。','计算先写ρ液而不是ρ物，再判断V排是否等于V物，将cm³换成m³后代入。实验验证时先把溢水杯装至口沿且等到不再滴水，称空接水杯，测物体空气中与液体中的示数，收集全部溢水后称杯水总重并扣空杯。比较G−F示与G杯水−G空杯是否在误差范围内接近。','体积500 cm³物体只有2/5浸在密度800 kg/m³的油中，V排=200 cm³=0.0002 m³，取g=10 N/kg，浮力是1.6 N。若误用500 cm³会算成4 N，若再误用物体自身密度则连对象都选错。题目说“完全浸没”才可直接把整个外部体积代入，漂浮时要另求浸入比例。',[['由浮力反求密度','重5 N实心物体完全浸水后测力计读3 N，浮力2 N，对应V=2/(1000×10)=0.0002 m³。其质量由m=G/g=0.5 kg得出，因此物体密度为2500 kg/m³。这里用了两条独立信息：空气中重力给质量，水中示数差给体积；不能用浸水后的3 N直接求物体质量。'],['为什么实验数据可能不一致','溢水杯起初未装满，会使部分排开的水留在杯内，实际收集的水重偏小；水洒出接水杯，也会偏小；没有扣掉空杯重力则偏大。物体上附气泡会额外排液，若忽略会影响体积测量；物体碰杯底会使称重法所得“浮力”混入支持力。分析误差要逐步追踪哪个测量量改变，不能只写“操作不规范”。']]);
D('p10-3','无其他竖直作用时，比较浮力与重力可判断物体的浮沉趋势：F浮>G时有向上加速趋势，F浮<G时有向下加速趋势，F浮=G时可以保持静止或原有匀速状态。静止漂浮与静止悬浮都满足F浮=G；漂浮物有部分体积露出液面，悬浮物完全浸在液体内部。','一块木头被全部压进水中，排水体积很大，浮力大于重力；松手后上浮。露出水面时，排水体积逐渐变小，浮力跟着减小，最终与重力相等而漂浮。石头全浸水时浮力小于重力，便会下沉。对于均匀实心物体，用ρ物与ρ液比较也能判断；空心船则要用包括空腔在内的总体平均密度，不能只看钢铁材料密度。','先判断物体是否全浸没，再判断有没有绳拉、支撑等额外作用。静止漂浮时直接用F浮=G求排液质量或体积，通常比先找形状更简洁。若给密度比，可由ρ液V排=ρ物V物求浸入比例。不要把“浮力等于重力”当作一切浸水物体的通用公式，它只在相应平衡条件下成立。','体积400 cm³、质量240 g的密闭物体平均密度0.6 g/cm³。在水中静止排水体积240 cm³，在密度0.8 g/cm³油中排液体积300 cm³，两次浮力都等于物体重力。油密度较小，因此需要排开更多体积才能托住它。换成较浓盐水后，排液体积减小但浮力不会继续增大。',[['轮船和潜水艇各改变什么','轮船把钢材做成大体积空心结构，使总排水体积足以提供很大浮力。排水量是排开水的质量，漂浮时等于船与货物总质量。潜水艇完全浸没后外部体积近似固定，通过向水舱充水或排水改变自身重量来下潜或上浮。这与压扁塑料瓶、改变总体积造成的浮力变化不是同一种控制方式。'],['趋势不等于即时速度','一个正在向下运动的物体即使突然浮力大于重力，也可能先继续向下但减速，之后才转为上升；合力方向决定速度变化，不直接决定当前速度。题目一般从静止释放或问最终状态时，才可直接用上浮、下沉简写。物体沉到底部后若底面仍与水接触，支持力与浮力共同承担重力；若底面密封贴合，则需重新分析液体压力。']]);
D('p10-4','密度计根据漂浮条件测量液体密度。同一支密度计在不同液体中静止漂浮，浮力始终等于它自身的重力；由ρ液gV排=mg可得ρ液=m/V排。因此液体越密，密度计需要排开的体积越小，浸入越浅。','把密度计看成一根底部有配重的小浮标。放在水中时它停在一个高度，换到密度更大的盐水中，同体积液体能提供更大浮力，浮标便上升一些以减少排水体积，直到重新平衡。虽然杆露出的长度增加，液面却对应杆上更靠下的位置，所以密度数值大的刻线写在下方，数值小的写在上方。','用密封吸管或细管制作，底部固定适量配重，让它能直立漂浮。先检查密封，在已知密度的液体中等待稳定后标记液面；再换几种已知密度液体标定并检查可测范围。读数时不碰壁不触底，除去附着气泡，视线与液面处对应刻线齐平。液体温度应尽量一致，因为密度会随温度改变。','质量12 g密度计在某液体中排开10 cm³，液体密度就是1.2 g/cm³。若同一密度计在水中排12 cm³，两次浮力完全相同。设细杆截面积不变，浸入长度与排液体积相关，而密度与排液体积成反比；因此不能在杆上简单等距写0.8、1.0、1.2而不做验证，普通密度刻度通常不均匀。',[['刻度疏密与灵敏度','相同密度变化在不同密度范围需要的排液体积变化并不相等，所以刻线间距也会不同。把杆做细，相同体积变化对应更大的高度变化，有利于看清小变化；但太细可能使漂浮不稳或可用量程受限。配重增加能改变漂浮位置，量程也应重新标定，不能拿一支密度计的刻度直接贴到另一支质量不同的管子上。'],['气泡和进水怎样造成误差','表面附着气泡会额外提供排液体积，密度计杆本身浸入偏浅，用原刻度读数通常偏大。若内部漏进水使密度计增重，它在同一液体中会浸得更深，按原刻度读数通常偏小，严重时沉没。若测量前发现密度计质量或密封状态改变，应修复并重新标定；重复测量无法消除结构已经改变造成的偏差。']]);
D('p11-1','如果物体受到力，并且沿这个力的方向移动了一段距离，就说这个力对物体做了功。在力恒定且与位移同方向的初中模型中，功等于力与距离的乘积：W=Fs。功的单位为焦耳，简称焦，符号J，1 J=1 N·m。','功描述力通过位移传递能量的过程，不等于人的辛苦程度。举着重箱子站着很累，但箱子没有位移，提力对箱子不做机械功；提箱子在平地水平走，竖直提力与位移方向垂直，也不做这一方向的功。人仍消耗身体能量，是生理过程与体内其他运动造成的，不能用“累不累”替代物理定义。','判断某力是否做功，先问这个力是否作用着，再问物体有没有移动，最后看位移是否沿力方向。有力无位移、有位移而该力不存在、力与位移垂直，都不能直接写正功。计算时明确“哪个力”“哪一段路程”，别把全程路程乘只作用在部分路段的力，也别将重力和拉力混用。','水平20 N拉力拉箱子3 m后撤去，箱子因惯性再滑2 m。拉力只在前3 m做功，W=60 J，而不是20×5=100 J。若问全程重力的功，因为位移水平、重力竖直，答案为零。一个运动过程不同力的功可以不同，所以题目中的力名必须保留到计算步骤里。',[['提升与沿斜面运动','把重100 N物体从地面搬到1 m高处，克服重力所做的功为Gh=100 J。即使绕长路或沿5 m长斜坡移动，重力方向的高度差仍只有1 m。沿斜面拉力的功却要用拉力与沿坡距离，例如30 N拉5 m做150 J；多出的50 J可能用来克服摩擦等阻力。功相同与路径相同不是一回事。'],['匀速也可能持续做功','箱子被拉着匀速直线运动，拉力与摩擦力平衡，合力为零，运动状态不变，但拉力仍沿位移做功，能量不断转为接触面的内能。不能因为合力零就把每个力的功都判零。若拉力35 N把重30 N物体向上提升2 m，拉力功70 J、克服重力功60 J，差额与物体动能增加等有关。']]);
D('p11-2','功与做功所用时间之比叫功率，公式为P=W/t。功率描述做功的快慢，单位为瓦特，简称瓦，符号W；1 W=1 J/s。千瓦是常用较大单位，1 kW=1000 W。功与功率分别回答“做了多少”和“做得多快”。','两台吊机都把同一堆货物提升到同样高度，有用功相同；十秒完成的比二十秒完成的做功更快，功率更大。但大功率机器只开一小会儿，做功可能少于小功率机器长时间工作。就像水龙头流量与总用水量不同，比较功率必须同时看功和时间。机械效率则比较输入功中有用的比例，又是另一个量。','求功率先求对应那部分功，再把时间换成秒。匀速提升可用P=mgh/t；恒力与速度同方向时，W=Fs和v=s/t合并为P=Fv。若车匀速行驶，牵引力等于阻力，可以先由阻力求F再算功率；若加速，不能无条件把牵引力当作阻力。平均功率与瞬时功率也应按题目给的时间范围区分。','60 kg学生在30 s内登高9 m，取g=10 N/kg，只计算克服重力：W=60×10×9=5400 J，P=180 W。若用20 s完成，功仍5400 J，功率变270 W。楼梯斜着走了多少米并不直接代入mgh，需测楼层之间的竖直高度；起步、转身等额外能量在这个估算里没有计入。',[['P=Fv为什么有用','汽车输出牵引功率若保持20 kW，平路匀速需要1000 N牵引力，则速度v=20000/1000=20 m/s。遇到较大阻力时可降低速度，在相同功率下得到较大牵引力。这并不意味着任何车辆降速都自动增大功率，也不说明发动机任何时候都以额定功率工作，需看题目是否给出恒定输出条件。'],['比例题与测量误差','两人登同一楼层时P与m/t成正比。若质量比3∶2、时间比2∶3，功率比为(3/2)/(2/3)=9∶4。实际测量要在约定起点开始计时，到达终点停止，测准楼高与质量。时间测得偏小会使计算功率偏大；用斜面路程当高度也会把有用功和功率高估。比值与误差都可以从公式逐项追踪。']]);
D('p11-3','物体由于运动而具有的能叫动能；物体由于被举高而具有的能叫重力势能；物体由于弹性形变而具有的能叫弹性势能。能量可用物体做功的本领来理解。动能与势能合称机械能，势能包括重力势能和弹性势能等。','同样的小球滚得越快，撞上相同木块后通常能把木块推得更远，说明动能越大。速度相同时较重的球通常也有更大动能。高处的水可以落下推动水轮，被拉开的弓可以弹出箭，它们虽然可能暂时静止，却因位置或形变储存了做功本领。能量不是一定已经做了功，而是具备转移和做功的可能。','定性比较时每次只改变一个因素：比较速度影响就用同质量球；比较质量影响就使碰撞前速度相同。重力势能比较需采用相同参考高度，质量越大、相对高度越高，势能越大。对同一弹簧比较形变大小时要保证仍在弹性限度内，不能把不同材料、不同尺寸弹簧只按伸长量直接比较。','滚球实验中，A球50 g、速度1 m/s推动木块4 cm，B球50 g、速度2 m/s推动16 cm，支持速度大时动能大；C球100 g、速度1 m/s推动8 cm，与A比较支持质量大时动能大。若B同时换了更轻木块或更光滑桌面，距离变长就不能单独说明球动能增加，这体现了转换法必须控制条件。',[['为什么要有统一参考面','同一箱子相对地面高3 m，相对楼板可能只有1 m，它的重力势能数值依赖选择的参考面，比较时必须统一。物体在同一高度但质量不同，质量大的重力势能较大；若一个更重却更低、另一个更轻却更高，只靠两个单向定性规律通常不能直接判断。题目给出了质量与高度数值时才可进一步比较质量和高度的乘积。'],['定性规律不要滥推倍数','同一球速度变大，能确定动能变大，但不能只凭“越快越大”就断言速度翻倍动能也翻倍；同一弹簧形变翻倍，也不能直接写势能翻倍。初中在没有给公式时常要求定性比较与实验设计。回答要与证据强度对应，既不漏掉另一影响因素，也不从一条趋势凭空造出线性关系。']]);
D('p11-4','动能与势能统称机械能，它们在一定过程中可以相互转化。系统若没有机械能因摩擦、空气阻力等转为其他形式，也没有外界向系统输入或取走能量，其机械能总量可保持不变。存在耗散时机械能可能减小，但能量并没有消失，而是转移或转化了。','滚下坡的小车越走越快，重力势能减少、动能增加；向上抛的球越升越慢，动能减少、重力势能增加。拉紧的弹簧松开后推动车，弹性势能变为动能。单摆从高处摆下再摆上，就把位置高低与速度快慢交替起来。现实摆动会逐渐减弱，因为阻力把部分机械能转成内能，并非违反总能量守恒。','分析先选对象或系统，例如球加地球、弹簧加小车；再列初末状态的高度、速度、形变。若题目允许忽略阻力，可列E动初+E势初=E动末+E势末；若有损耗，则在末态机械能旁加上转出的其他能量。能量守恒是账目完整，不是规定每一种能量都保持不变。','一个球初时动能20 J、势能30 J，总机械能50 J；无阻力到另一处势能10 J，则动能40 J。若过程中摩擦等损耗5 J，末动能应35 J。另一个重10 N小球从高5 m静止下落，到高2 m处动能24 J，初机械能50 J、末机械能44 J，差6 J转成了其他形式。',[['最高点与最低点的受力','竖直上抛球在最高点速度瞬间为零，动能为零，但仍受竖直向下重力，并有相对地面的重力势能。摆球在最低点动能最大，但重力仍存在，还需绳拉力改变运动方向。能量最大或最小的状态不能替代受力分析；“速度为零”和“合力为零”也完全不是同一句话。'],['不同路径与外界供能','同一球从相同高度沿两条无摩擦轨道到同一低点，重力势能减少量相同，末动能与末速大小相同，尽管到达时间可以不同。若有人不断蹬动秋千，摆幅变大，是人通过动作把体内化学能转移到秋千系统；这时不能套机械能总量不变。看到高度增加，应寻找输入能量来自哪里，而不是把它称为能量凭空增加。']]);
D('p12-1','在力的作用下能绕固定点转动的硬棒叫杠杆。固定点是支点，促使杠杆转动的力叫动力，阻碍其转动的力叫阻力。支点到动力作用线的垂直距离叫动力臂，支点到阻力作用线的垂直距离叫阻力臂。平衡时F₁l₁=F₂l₂。','把门把手安排在远离门轴的位置，是为了让相同力产生更明显的转动效果。杠杆的关键不仅是多大力，还有力的作用线离支点多远。力臂是垂直距离，杠杆本身即使很长，若用力方向正好穿过支点，力臂仍为零，几乎不能让它转动。示意图里要先延长力的作用线，再从支点作垂线，而不是直接量支点到手的斜线。','解题先找支点，画动力、阻力及其作用线，作两条垂线确定力臂，再判断两力转动效果是否相反并列平衡式。动力臂长于阻力臂时所需动力小，属于省力杠杆；短于则费力但能让工作端移动更大距离。杆重不可忽略且重心不在支点时，还要加入杆重的转动效果。','轻质杠杆左端30 N、右端10 N，两端相距0.8 m。设支点距左端x，左右力臂为x与0.8−x，平衡有30x=10(0.8−x)，得到x=0.2 m。较重一侧靠近支点，较轻一侧离得远。若把30 N侧力臂错写成全长0.8 m，等于忽略了支点真正位置。',[['如何寻找最小动力','若动力只能作用在杠杆某个固定端点，要使动力最小，就要使力臂最大。支点到该端点的连线长度固定，当动力垂直于这条连线时力臂最大；将力倾斜会缩短垂直力臂，所需力增大。若可改变作用点，则也可向远离支点处移动，但要保持杠杆强度和结构限制，不能把长度无限延长当成实际工程方案。'],['杠杆实验的细节','实验前调平衡螺母，让未挂钩码的杠杆水平；正式改变挂码后不要再随意移动平衡螺母，否则改变了原来的重力影响。各组记录动力、动力臂、阻力、阻力臂，比较两边乘积。一次数据相等不足以发现普遍规律，应在多组不同力和距离下检验。竖直挂力且杆水平时，可直接用刻度读力臂，斜拉则不能照抄杆长。']]);
D('p12-2','杆秤是利用杠杆平衡测量质量的工具。提纽相当于支点，秤盘或秤钩承载待测物，秤砣沿秤杆移动以改变其力臂。秤杆水平静止时，两侧重力的转动效果平衡。经过空盘调零后，待测物质量增量与秤砣相对零点移动距离成正比。','“秤砣虽小”能平衡较重物体，是因为秤砣可以离支点很远，而待测物一侧力臂较短。杆秤不省功，也不是让重物变轻，而是用更长力臂补偿较小重力。制作时不能忽略杆和空盘本身的重量：先把空盘挂好，移动秤砣调到水平并标零线，这个零点已经包含固定结构的重力矩。','先选坚固直杆并固定提纽、秤盘位置，系上固定质量秤砣，调零，再用多个已知质量砝码逐次标定。称量时保持提纽位置、秤砣质量和盘的位置不变，移动秤砣到杆水平后按悬线读数。理想关系为m物l物=m砣Δl，其中Δl是秤砣从零刻度移动的距离，不一定是从支点量起的完整距离。','待测一侧力臂4 cm、秤砣50 g，空盘已调零。称150 g物体时，150×4=50Δl，得到Δl=12 cm。若零刻度本身在距支点3 cm处，最终悬线应在距支点15 cm处。把12 cm误当最终绝对位置就会少移3 cm，这是杆秤计算最常见的概念差别。',[['量程与精细度的取舍','砣质量一定、杆上可移动距离一定，减小待测物侧力臂可称更大质量，但每增加同样质量所对应的砣位移变小，刻度更密；换更重秤砣也有类似效果。因此设计不能只追求大称量范围，还需考虑最小刻度是否看得清。更换提纽或秤砣后要重新标零和标刻度，不能继续沿用旧读数。'],['用误差分析检验可靠性','秤砣变轻后，要平衡同一物体就需移得更远，用原刻度读数通常偏大；换成更重的秤盘却未调零，也会把盘重增加误记到物体上。若秤杆倾斜，力臂关系和标定状态可能改变，且容易读错位置。制作报告应包含零点检查、已知质量复测、多次读数、最大可测质量与可能误差，让设计结果可验证。']]);
D('p12-3','轴的位置固定不动的滑轮叫定滑轮，轴随重物一起移动的滑轮叫动滑轮。定滑轮理想情况下不省力，但能改变用力方向；一个由两股绳承担负载的理想动滑轮可省一半力。由定滑轮与动滑轮组合构成的滑轮组，可兼顾省力与改变方向。','省力不是白得的好处。两股绳托着一个动滑轮，物体向上1 m，每一股承担部分负载的绳都缩短1 m，所以自由端要拉动2 m。三股承重则要拉3 m。即使用更小力，手走过的路程也相应增加；不计损耗时输入功与输出功相等。实际还要抬起动滑轮本身、克服转轴摩擦，所以人做的功通常更多。','把随重物运动的滑轮与货物圈成一个整体，数外界绳子对这个整体向上的拉力有几股，设为n。同一根轻绳且忽略滑轮摩擦时张力相等，匀速提升满足nF=G物+G动，绳端位移s=nh、速度v绳=nv物。数绳段不能只数图上画了几条线，也不能用滑轮个数直接代替n。','三股绳承担货物240 N与动轮30 N，理想拉力F=(240+30)/3=90 N。提升0.5 m，绳端走1.5 m，手做功135 J，其中120 J提升货物、15 J提升动轮。若题目说轮重忽略才可把30 N去掉；轮重给出时直接算240/3=80 N就少计了一部分负担。',[['定滑轮与动滑轮别混淆','看轮轴是否随重物移动，比看它画在上面还是下面更可靠。上方固定轮的支架承受绳两侧张力等作用，它自己不随货物升高，所以不作为移动整体的重力负担；下方轮若随货物一起升高，其重量就必须计入。在非竖直拉绳或复杂绕法中，需真正画出各绳段方向，不能盲用简单n股竖直承重公式。'],['从位移反推结构','若测得货物上升0.4 m，自由绳端移动1.2 m，可以推知理想情况下n=3。再结合测得拉力80 N和动轮30 N，得到货重3×80−30=210 N，g=10 N/kg时质量21 kg。若结果与实际称重不一致，可检查绳端位移读错、摩擦未计、轮重遗漏等。速度与距离倍数常用于检查受力计算是否合理。']]);
D('p12-4','为达到工作目的而必须做的功叫有用功；对工作目的没有直接贡献但又需要付出的功叫额外功；二者之和叫总功。有用功与总功的比值叫机械效率，η=W有用/W总×100%。机械效率表示输入能量用于目标任务的比例。','吊机把货物抬高，提升货物是目标；同时抬起动滑轮、克服轴承摩擦等则是额外负担。总输入100 J，其中80 J用于货物，效率就是80%，并不是只用了20%的力，也不是每秒做80 J功。省力描述力的大小，功率描述快慢，效率描述比例，三个指标可以分别比较，不能互相替代。','先定义任务，再分别列有用功和总功。滑轮组提升货物时W有=G物h，W总=Fs，s=nh；斜面提升时W有=Gh，W总=F沿坡×坡长。效率要用同一工作过程的数据，数值通常小于100%。若计算超过100%，先检查单位、受力、距离和示数，不能把超出的部分说成机械创造了能量。','三股承重组用100 N拉力把240 N货物提升2 m。绳端走6 m，总功600 J，有用功480 J，所以效率80%，额外功120 J。若错把物体高度2 m当绳端路程，会算总功200 J，出现240%的假效率。几何距离关系与功的对象一样重要，先画图标h和s能减少这种错误。',[['提高效率的条件','动轮重20 N且忽略摩擦时，提升80 N货物，η=80/(80+20)=80%；提升180 N货物，η=180/200=90%。同一机械增加有效负载后，固定额外负担占比下降，所以效率提高，但必须在器材安全范围内。润滑轴承、减轻动轮也可降低额外功。若摩擦随负载明显变化，则不能无条件沿用这个简单比值。'],['斜面、实验与评价','重100 N物体沿长5 m、高1 m斜面被30 N拉力匀速拉上，W有=100 J、W总=150 J，效率约66.7%，额外50 J主要用于摩擦。实验中应匀速拉，避免示数混入加速阶段；测物重、拉力、高度和绳端或斜面距离，并记录单位。效率高的机器未必功率大，同样把能量用得好，也可能工作得较慢，选择工具要根据实际目标比较。']]);

const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const tx=(x,y,s,size=17,color='#24443f',anchor='start')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${color}" text-anchor="${anchor}">${esc(s)}</text>`;
const ln=(x1,y1,x2,y2,color='#45665e',width=3,dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${width}"${dash?` stroke-dasharray="${dash}"`:''}/>`;
const rc=(x,y,w,h,fill='#dceee7',stroke='#35745f')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="5" fill="${fill}" stroke="${stroke}" stroke-width="2"/>`;
const circ=(x,y,r,fill='#f2c879')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="#45665e" stroke-width="2"/>`;
const arr=(id,x1,y1,x2,y2,color='#17765f')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="3" marker-end="url(#${id}-${color==='#b05b39'?'b':'a'})"/>`;
const water=(x,y,w,h,level)=>`<path d="M${x} ${y}V${y+h}H${x+w}V${y}" fill="none" stroke="#53756e" stroke-width="3"/><path d="M${x+2} ${level}H${x+w-2}V${y+h-2}H${x+2}Z" fill="#d8eef4"/>${ln(x+2,level,x+w-2,level,'#71aabd',2)}`;
const svg=(id,title,body)=>`<svg class="lesson-diagram" viewBox="0 0 720 360" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(title)}"><defs><marker id="${id}-a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#17765f"/></marker><marker id="${id}-b" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#b05b39"/></marker></defs><rect width="720" height="360" rx="16" fill="#f8fbf9"/><g font-family="system-ui,-apple-system,sans-serif">${body}</g></svg>`;
export const physicsVisuals8L={};
const V=(id,title,body,caption)=>{physicsVisuals8L[id]={title,svg:svg(id,title,body),caption};};
V('p7-1','画出力的三要素',rc(250,140,160,85)+circ(330,180,5,'#24443f')+arr('p7-1',330,180,545,180)+tx(455,157,'F = 6 N')+tx(310,254,'作用点')+ln(328,237,330,191,'#8aa59a',2)+tx(520,213,'方向 →')+tx(58,52,'同一对象 · 确定大小 · 箭头标方向',21)+tx(68,302,'示意图中的箭头线段从作用点出发；线段长短可比较力的大小。',17),'箭头起点表示作用点，指向表示方向，标注表示大小；物体大小与图中力的线长没有换算关系。');
V('p7-2','原长、伸长量与测力计读数',ln(65,65,325,65)+ln(110,65,110,95)+`<path d="M110 95l-15 8 30 8-30 8 30 8-30 8 30 8-15 8v22" fill="none" stroke="#35745f" stroke-width="3"/>`+ln(260,65,260,95)+`<path d="M260 95l-15 13 30 13-30 13 30 13-30 13 30 13-15 13v22" fill="none" stroke="#35745f" stroke-width="3"/>`+rc(240,218,40,40,'#f2c879')+ln(68,173,350,173,'#9aada5',2,'6 5')+ln(280,218,350,218,'#9aada5',2,'6 5')+tx(70,44,'空载')+tx(228,44,'加载')+tx(302,203,'ΔL')+tx(65,301,'伸长量 ΔL = 现长 L − 原长 L₀')+arr('p7-2',420,264,660,264)+arr('p7-2',420,264,420,60)+ln(420,264,615,105,'#b05b39',4)+tx(600,298,'伸长量')+tx(435,65,'拉力')+tx(435,327,'限度内：F 与 ΔL 成正比',16),'左图比较原长与拉长后的长度；右图强调在适用范围内比较拉力与伸长量，不能用弹簧总长代替伸长量。');
V('p7-3','斜面上的重力仍竖直向下',`<path d="M90 278H485L485 90Z" fill="#e3e9df" stroke="#7c9788" stroke-width="2"/><g transform="rotate(-25.5 313 171)">${rc(268,131,90,50)}</g>`+circ(314,169,4,'#24443f')+arr('p7-3',314,169,314,294,'#b05b39')+tx(330,264,'G = mg')+ln(525,64,525,246,'#8aa59a',2,'5 5')+circ(525,247,13)+tx(545,178,'铅垂线')+tx(75,330,'重力：地球施加 · 竖直向下 · 从重心画出',18),'斜面倾角不改变重力的竖直方向。图中仅画重力，支持力与摩擦力需在完整受力分析时另画。');
V('p8-1','阻力越小，相同初速度的小车走得越远',[['毛巾',125,280],['木板',210,440],['更光滑',295,625]].map(([label,y,end])=>tx(40,y-17,label)+ln(155,y,end,y,'#9cafa5',5)+rc(160,y-32,45,25)+circ(170,y-3,5)+circ(195,y-3,5)+arr('p8-1',215,y-18,end,y-18)+tx(end+5,y-12,'停止',14)).join('')+tx(42,48,'每次进入水平面的速度相同',22)+tx(375,78,'理想推理：若不受力，保持匀速直线运动',16),'三次比较控制小车和初速度相同，只改变表面阻力；“无力时永远匀速”属于基于实验趋势的理想推理。');
V('p8-2','同一物体上的二力平衡',rc(150,143,130,80)+ln(85,225,360,225,'#8ba090',6)+circ(215,183,4)+arr('p8-2',215,183,215,70)+arr('p8-2',215,183,215,298,'#b05b39')+tx(235,82,'N = 20 N')+tx(235,296,'G = 20 N')+tx(425,102,'同一个物体',22)+tx(425,145,'大小相等')+tx(425,184,'方向相反')+tx(425,223,'作用在同一直线上')+tx(420,295,'静止或匀速直线运动',18),'支持力与重力都作用在方块上，可以平衡；方块对桌面的压力作用于桌面，不画在这个对象的受力图上。');
V('p8-3','匀速水平拉动时，拉力等于滑动摩擦力',rc(280,130,140,90)+rc(310,88,80,40,'#f2c879')+ln(55,224,665,224,'#a0af98',8)+arr('p8-3',420,175,595,175)+arr('p8-3',280,212,105,212,'#b05b39')+tx(500,151,'拉力 F')+tx(106,193,'摩擦 f')+arr('p8-3',318,53,416,53)+tx(318,36,'匀速运动 v')+tx(80,293,'研究压力：接触面相同，只增减砝码。')+tx(80,326,'研究粗糙程度：总压力相同，只更换接触面。'),'木块匀速直线运动时水平两力平衡；砝码用于改变压力。摩擦箭头沿接触面，与木块相对桌面的滑动方向相反。');
V('p8-4','共线力：同向相加，反向相减',tx(50,45,'同一物体，同一直线',22)+rc(125,87,85,55)+arr('p8-4',210,114,315,114)+arr('p8-4',315,114,465,114)+tx(230,91,'3 N')+tx(364,91,'5 N')+tx(512,120,'合力 → 8 N')+rc(275,216,85,55)+arr('p8-4',275,243,180,243,'#b05b39')+arr('p8-4',360,243,515,243)+tx(182,217,'3 N ←')+tx(422,217,'8 N →')+tx(545,249,'合力 → 5 N')+tx(70,324,'反向时，合力朝较大力的方向；合力不是额外新增的力。',17),'上图两同向力用相邻箭头辅助示意相加，下图反向力相减。只合成同一对象的力，不能合成分属两个物体的相互作用力。');
