const extend=(id,title,body)=>physicsDetails8L[id].sections.push({title,body});
extend('p7-1','从实验记录作出有依据的结论','同一个人在门把手处垂直推门，比在门轴附近推更容易，这个比较只有在推力大小基本相同、门的初始状态一致时才主要反映作用点的影响。若第二次同时增加推力，就出现两个变量，不能只写“证明力的作用点影响效果”。读数据题也要先看条件是否受到控制，再比较结果。比如球速从每秒一米变为每秒三米，随后速度大小不变但方向转弯，两个阶段都可能是运动状态改变；最后静止时也不能仅凭结果断言所有力消失。清楚区分观察结果、可能原因和能支持的结论，是力学实验答题的重要步骤。');
extend('p7-2','从长度表格识别规律与量程','整理弹簧表格时可先算相邻两次拉力差与长度差，看每增加相同拉力是否增加相同长度。若前面规律稳定，最后一次伸长突然明显异常，应检查是否超过弹性限度、弹簧卡滞或读数出错，不能盲目延长直线。两根弹簧即使某次总长度一样，原长可能不同，伸长量也不同；要比较谁更容易被拉长，应在相同拉力下比较各自伸长量。把测量方向、零点、量程与单位一并记录，能让另一位同学重现实验，而只写一个没有单位的数字无法完整表达测量结果。');
extend('p7-3','把图像、斜率和单位联系起来','若横轴是质量、纵轴是重力，同一地点测得的数据通常近似落在过原点的直线上。任取一点用重力除以质量，得到当地的重力与质量比值；不要把横纵轴交换后仍按原来顺序相除。比如零点已校准，质量增加二百克而重力增加二牛，先将二百克换成零点二千克，才得到每千克十牛。若图像不过原点，先检查测力计是否调零或是否漏扣挂钩、空盘重力，再讨论是否仍呈正比例。实际数据小幅波动可来自测量误差，不宜只保留最符合预期的点。');
extend('p8-1','用反例检查自己的解释','若有人说“车越快惯性越大”，可以保持同一辆车的质量不变，分别讨论静止、慢行和快行：惯性大小都不变，但动能与刹车距离可能明显不同。若有人说“没有力就没有速度”，可以用光滑面上的滑行趋势反驳：减小阻力反而延长运动。解释乘车转弯时也要把车与乘客分开，车受到转向作用改变方向，乘客有保持原方向的趋势。只有明确对象和原来状态，才能避免把惯性说成受力，或把一个看起来合理的生活描述误当成物理定义。');
extend('p8-2','多一个力时怎样列平衡关系','物体静止并不一定只受两个力，二力平衡只是最简单情况。一个重五十牛的箱子被向上提十牛同时放在桌上，就有三种竖直作用：重力、提力、支持力。先把所有向上力加起来与向下重力相等，可得支持力四十牛；箱子对桌面的压力再由相互作用关系求出，也是四十牛。此时不能因为箱子静止就写“支持力等于重力”。同理，水平拉力与两个阻力共同作用时，应把阻力总和与拉力比较。平衡是整体效果相抵消，具体的两个力是否构成平衡力还要另检查。');
extend('p8-3','静止、启动与滑动是不同阶段','推箱子的力逐渐增加时，箱子若一直静止，静摩擦力也随之增加以保持平衡，直到达到所能提供的最大静摩擦附近才可能开始滑动。开始滑动后，若接触条件不变，摩擦力往往近似稳定，拉力继续增加主要改变合力。中考常把三个阶段画在一张拉力随时间图上，必须结合速度或运动状态图判断每段属于静止、加速还是匀速，不能把每段的拉力都直接当成摩擦力。只有已知匀速直线运动且水平方向仅这两个力时，示数才可直接等于滑动摩擦力。');
extend('p8-4','合力图不能替代速度图','同一个向左合力可以对应至少几种情形：原来静止的物体开始向左运动；原来向左运动的物体加速；原来向右运动的物体先减速。因此题目既给拉力变化又给运动方向时，要分两步回答：先求合力大小和方向，再根据原速度方向判断快慢变化。若题目只给某个时刻合力为零，不能补充说物体必然静止。合力概念的作用是概括多个作用的共同效果，而不是用一个箭头取代完整的运动信息。画图时给力箭头和速度箭头分别标注符号，可以有效减少混淆。');
extend('p9-1','组合物体的压力传递','把小砖放在大砖上，大砖放地面，研究小砖对大砖的压强时，压力主要来自小砖重力、面积是两砖实际接触面；研究整个装置对地面的压强时，要算两砖总重、面积取大砖底面。上下接触面的压力和面积都可能不同，不能用同一套数字计算所有位置。如果再有人从上面向下按压，力会通过接触传递，地面承受压力也增大；若从上方提住部分重量则相反。把每个接触面画出来并圈出其上方被支持的整体，能帮助选对压力，也能发现题目是否遗漏了额外支撑。');
extend('p9-2','同一容器倾斜以后看什么','装液体的容器缓慢倾斜后，如果没有流出液体，液体总重可以不变，但底部某位置距自由液面的竖直深度可能变化，因此该位置压强也可能变化。不能因为水量不变就断言水压不变。若容器底面已经倾斜，同一底面不同点深度不同，压强不再处处相等，初中题中应按给定点求压强，不宜随意拿其中一点的压强乘整块底面积。当题目说“水平底面”并且整个底面处于同一深度时，才适合直接用同一个压强计算整块底面上的压力。');
extend('p9-3','用压强差而非单侧压强回答','密闭注射器内气压低于外界时，活塞两面都受气压，实际推动活塞的是两侧作用之差。若内外压强逐渐相等，净气压作用会减小到零，但不能说大气压不存在。覆杯、吸盘等实验也一样，密封状态决定差值能否维持，接缝进气后可能失效。估测大气压时若用注射器活塞面积与拉力计算，还要留意活塞摩擦，摩擦若被全部当成气压力会使估值偏差。解释实验失败要追踪密封、摩擦、面积与读数，而不是简单认定某条规律失效。');
extend('p9-4','把制作结果变成可比较的数据','可以固定水源与泵之间的高度、活塞行程和完成次数，比较改进密封前后的出水体积，再重复几轮求平均。若想研究往复频率，应该每次记录相同时间内的完整循环数与出水量，区分每循环排水量与单位时间流量。只展示“终于出水”的视频不能证明某方案更高效。还可把材料成本、可拆卸清洗、阀片寿命列为设计评价项，因为好用的装置需要物理原理正确，也需要结构可靠。遇到卡住应停止并检查，不能用过大力量把薄塑料筒挤裂。');
extend('p9-5','读图时分清气流箭头和受力箭头','原理图中经常同时出现空气流动方向、物体运动方向和压力箭头，三者含义不同。气流向右并不意味着物体必定受向右合力；若物体上下两侧流速不同，压力差可能朝上或朝下。应先读标注，找到比较的是哪两侧流速，再判断压强与受力。若已给机翼升力与重力，还应计算净力；升力大于零不能直接说明飞机正在上升，因为升力也可能刚好平衡重量，或者小于重量使飞机向下加速。完整结论要把流动、压强、力与运动这几步逐一连接。');
extend('p10-1','从示数变化图识别浸没点','将物体匀速缓慢压入液体，测力计示数常先逐渐减小，完全浸没后出现近似水平段。转折处对应排液体积刚好不再增加，可用重力与水平段示数之差求全浸浮力，再进一步求总体积。若继续下放后示数又突然减小，应检查是否触底，不能把所有示数降低都解释为浮力增加。若物体为可压缩气囊，深处体积减小也会影响曲线，所以使用“平台表示全浸没”结论前应确认物体体积固定、液体密度均匀且没有接触其他支撑。');
extend('p10-2','从两次浸没测量识别未知液体','同一体积不变物体在空气中重六牛，在水中静止示四牛，在未知液体中示三点六牛，则水中浮力二牛、未知液体中浮力二点四牛。两次排液体积相同，浮力之比等于液体密度之比，因此未知液体密度是水的一点二倍。这里应比较“重力减示数”的结果，不能直接把两个测力计示数作比。若第二次仅部分浸入，排液体积不同，这种简便比例就不能使用。题目中的“同一物体”“均全浸没”“不触底壁”分别提供质量、体积与受力条件。');
extend('p10-3','载重增加与水位变化','把货物逐渐放上漂浮小船，总重增加，浮力也必须增加，因此船会多排开一些水。新增排水体积等于新增质量除以液体密度，与船原来已经排开的体积要分开计算。若把同一块物体从船内移到水里，水位是否变化则要比较两种状态排水体积：在船上由重量决定排水，在水里若沉底则由物体自身体积排水，若漂浮仍由重量决定。先分别列出两种状态的排水量，再比较，能解答许多看似复杂的船载与液面升降问题。');
extend('p10-4','确定量程而不只画漂亮刻度','一支八克密度计最多能排开十立方厘米液体，理想最低可测密度为每立方厘米零点八克；若液体更稀，即使全浸也托不住它。实际使用还需留出露在液面以上的可读部分，所以最低量程应保留余量。较高密度端则要检查液面是否仍落在细杆刻度区，不能落到配重粗大部分却继续沿用同样关系。设计完成后用量程内多个已知密度样本复核，注明温度和读数位置，比只在清水里画一道线更能证明工具可用。');
extend('p11-1','先分段再合计','一个过程可能同时有水平搬运、竖直提升、停顿和自由滑行，应分别判断指定力在哪些阶段存在、位移是否沿其方向。把重六十牛物体先匀速提升半米，再水平搬运四米，最后举着不动，竖直提力只在提升段做三十焦功；后两段不能把路程或时间直接加入。若放下物体时重力帮助运动，涉及功的正负则按题目范围处理，初中常直接问克服重力的功以避免混淆。最可靠的草稿是画一个分段表，每段写力、相应距离、是否做功，然后才合计。');
extend('p11-2','从图像读取功率','若横轴是时间、纵轴是已做的功，直线越陡表示相同时间完成更多功，功率更大。只看终点高度会混淆功与功率，应比较功的增量除以相应时间增量。若图线不是过原点，某一阶段平均功率要用阶段前后的功差与时间差计算，不能把纵坐标总值直接除以阶段持续时间。若横纵轴换成时间与功率，图线高度才直接表示功率，保持功率不变时所做功可由功率乘时间得到。读图先确认量名和单位，比先找看起来熟悉的线更重要。');
extend('p11-3','实验中的转换指标也要解释','用木块被推动距离表示球的动能大小，是把难直接测的能量转换成易观察的位移。这个方法之所以成立，依赖木块质量和表面阻力等条件可比，并假定碰撞过程能量转移方式接近。若换成另一块更轻木块，同样能量就可能把它推得更远，距离变化不再只反映球动能变化。答题应同时写“观察什么”和“为什么可比较”，而不是背一句转换法。研究势能也可让不同高度落下的物体对相同材料产生压痕，但要确保材料厚度、硬度与落体形状等保持一致。');
extend('p11-4','用能量账本找遗漏','在含弹簧的运动中，不能只列动能和重力势能：弹簧压缩或拉伸时还储存弹性势能。若球撞上弹簧后停止，动能不一定都成内能，也可能主要暂存在弹簧中，随后又把球弹回。若系统包括电动机或人，可能有电能或化学能输入。给每一种能量单独写“增加、减少或不变”，再看总和和流向，容易发现遗漏的储能部分。中考解释题常重视这种完整链条，机械能减少的量对应哪些其他能量，不应只写一句“有损失”而说不清去处。');
extend('p12-1','读图寻找力臂的步骤','遇到斜杆或弯杆，先用一个点标支点，再沿箭头方向把力的作用线画成直线，从支点向这条线作垂线，垂线段才是力臂。支点到作用点的连线只有与力垂直时才能直接作力臂。两个方向相反的力也未必产生相反转动效果，例如分别作用在支点两侧的上下力可能让杆朝同向转。列平衡式前可想象只保留一个力时杆会顺时针还是逆时针转动，再分组相加。这样即使有杆重、多个挂物或斜拉，也能逐项处理，而不是只看左右位置。');
extend('p12-2','用两点标定再用第三点检验','可以先用空盘确定零线，再挂一百克砝码确定一个刻度，以两点之间的距离按比例标出中间质量。随后用五十克和一百五十克分别复测，检查是否都能水平平衡。若只有一个点恰好准确，其他点系统偏差明显，应检查提纽是否滑动、秤砣是否碰杆、秤盘位置是否改变，或者零线记录错误。杆秤理想刻度均匀来自固定结构的线性平衡关系，而非所有测量工具都天生等距。将测量记录与结构草图保留，后续维修或更换零件时才能可靠重新标定。');
extend('p12-3','同时用力与距离核对','求得拉力后可用输入功与输出功做一次独立核对。若理想两股承重装置提升重一百牛货物一米，拉力应五十牛，绳端移动两米，两者乘积都是一百焦。若算出拉力五十牛却又写绳端只走一米，就会得到输入功少于有用功，说明距离关系出错。若动轮还有二十牛，拉力改为六十牛，总输入一百二十焦，其中二十焦用于提升轮子。这个检查把省力、费距离和机械能三者连接起来，也能提醒我们机械不能在未供能时凭空增加输出。');
extend('p12-4','实验读数与结果可信度','测力计应在匀速拉动中读数，而不是停下来才读，因为静止时轴与绳间摩擦状态可能不同。提升高度与绳端路程必须选相同起末时刻；若绳子松弛的一段也算进路程，会把总功估大，使效率偏小。若把拉力读大，也会使效率偏小；若把货物高度读大则有用功被高估，效率偏大。逐个追踪分子和分母的变化，可以解释误差方向。多次测量用于检查稳定性，而不是挑选最接近理论的结果；记录真实数据后说明偏差来源，才是有效的实验评价。');
// 复核后完善实验条件与分层挑战；保留题目ID和每课16题。
const findLesson=id=>physicsUnits8L.flatMap(u=>u.lessons).find(l=>l.id===id);
const revise=(id,n,q)=>{findLesson(id).questions[n-1]={...q,id:`phy-${id}-${n}`};};
revise('p7-1',12,c(3,'甲乙在同一扇门的同一作用点用相同大小的力推门，甲垂直门面、乙沿门面指向门轴。甲更容易推开门。要用此实验判断力的三要素影响，下列结论最严谨的是？',['大小相同，因此两次效果必相同','主要比较方向，作用点与力大小受到控制','同时验证了作用点与大小的影响','说明沿门面的力一定不存在'],1,'同对象、同作用点、同大小，仅方向不同，因此主要检验力方向对效果的影响。不能把没有转动效果说成没有力。'));
revise('p7-1',11,c(3,'甲用10 N向右推箱子，箱子给甲反向10 N的力；箱子还受地面向左6 N摩擦。关于受力对象与合力，正确的是？',['甲对箱子与箱子对甲的力抵消，箱子水平合力为0','箱子水平合力向右4 N，箱子对甲的力不画在箱子受力图上','箱子水平合力向右14 N','箱子水平合力向左6 N'],1,'箱子受到甲推力10 N向右及摩擦6 N向左，合力4 N向右。相互作用力分属两个对象，不能互相抵消。'));
revise('p7-1',14,t(3,'同一图中4 N力画成2 cm。箱子受向右6 N推力和向左2 N摩擦力，若将两力的共同效果画成一个力，其线段应长多少cm？只填数值。',['2'],'合力6−2=4 N向右。该图每1 cm表示2 N，所以合力画2 cm；先求合力再换算线段长度。'));
revise('p7-1',15,c(3,'实验记录：A在门把手处用5 N垂直推，B在同处用8 N垂直推，C在门轴附近用8 N垂直推。门初始状态相同。下列比较与研究因素对应正确的是？',['A与B比较作用点；B与C比较大小','A与B比较大小；B与C比较作用点','A与C能单独比较方向','三个实验只能研究门质量'],1,'A、B同点同方向，只变大小；B、C同力同方向，只变作用点。A、C同时改大小与作用点，不能单独归因。'));
revise('p7-2',11,c(3,'两只相同、轻质、已调零的测力计串联水平静止，左端固定在墙，右端用4 N水平拉。忽略摩擦，每只示数为？',['各2 N，因为平分外力','各4 N，因为串联每处张力均为4 N','靠墙8 N、另一只4 N','各0 N，因为整体合力零'],1,'从右侧测力计受力平衡可得连接处张力4 N，再对左侧分析也为4 N；串联不会把张力一分为二。'));
revise('p7-2',12,c(3,'某测力计空载指针为0.2 N未调零，挂物静止读3.2 N。将同一物体匀速向上提升，零误差不变，则读数与真实拉力为？',['读3.2 N，真实3.0 N','读3.4 N，真实3.2 N','读3.0 N，真实3.2 N','读数一定随速度增加'],0,'静止和匀速上升均无加速度，真实拉力都是3.0 N；固定正零误差0.2 N，读数均3.2 N。'));
revise('p7-3',13,c(3,'金属块从地面移到g为地面1/6的星体，形状体积不变。若原质量3 kg、重30 N，正确组合是？',['质量0.5 kg，重5 N，密度减为1/6','质量3 kg，重5 N，密度不变','质量3 kg，重30 N，密度不变','质量18 kg，重180 N，密度增大'],1,'地点改变g而不改变物质多少，质量仍3 kg；重力变30/6=5 N；体积不变故密度不变。'));
revise('p7-3',15,c(3,'甲乙物体质量比3∶2，分别放在g比为4∶5的两处。两物体重力比为？',['3∶2','6∶5','15∶8','5∶6'],1,'G甲/G乙=(m甲/m乙)×(g甲/g乙)=(3/2)×(4/5)=6/5；不同地点不能直接用质量比作重力比。'));
revise('p8-1',11,c(3,'质量相同的甲乙车初速分别10 m/s和20 m/s。刹车时所受阻力相同，忽略其他能量变化。已知动能随速度平方增大，以下判断正确的是？',['乙惯性是甲2倍','乙惯性与甲相同，但需阻力做更多功才能停下','两车惯性相同所以停车距离相同','乙停下后失去惯性'],1,'惯性由质量决定，两车相同；乙初动能更大，要由阻力转移更多能量，停车距离更大。题干给出动能关系，不能把距离差异归因为惯性改变。'));
revise('p8-1',14,t(3,'小球以3 m/s向右运动，所有力瞬间消失；从同一点同时出发的观察车以1 m/s向右匀速运动。4 s后球在车前多少m？',['8'],'无力后球保持3 m/s，球走12 m，车走4 m，相对距离12−4=8 m。'));
revise('p8-2',11,c(3,'水平箱子原以20 N拉力向右匀速运动。保持压力与接触面不变，把拉力增至30 N，仍向右滑动，采用滑动摩擦近似不随速度变化的模型。此时摩擦和合力分别为？',['摩擦30 N、合力0','摩擦20 N、合力向右10 N','摩擦10 N、合力向右20 N','摩擦20 N、合力向左10 N'],1,'原匀速阶段确定滑动摩擦为20 N；条件未变摩擦仍20 N，新合力30−20=10 N向右。'));
revise('p8-4',14,t(3,'箱子初受向右10 N拉力与向左6 N阻力，现把拉力减至4 N，阻力仍6 N。若再加一个共线力使合力恢复成原来的大小和方向，新增力应为多少N？只填大小。',['6'],'原合力向右4 N；修改后合力向左2 N，要恢复向右4 N，需再加向右6 N。'));
revise('p9-4',15,c(3,'改进泵后，每循环实际出水量由40 mL增为50 mL，但每分钟循环数从30次减为20次。新旧每分钟流量相比？',['增加25%','减少约16.7%','不变','减少50%'],1,'旧流量40×30=1200 mL/min，新流量50×20=1000 mL/min，减少200/1200≈16.7%。单循环更好不保证总流量更高。'));
revise('p10-1',15,c(3,'重10 N、体积1.2 L的密闭物体全浸水中，ρ水1000 kg/m³、g10 N/kg。将它静止限制在水中，且无接触底壁，则需要？',['从上方提供2 N向上拉力','从下方提供2 N向下拉力','从下方提供22 N向下拉力','不需约束'],1,'V=0.0012 m³，浮力12 N大于重力10 N，需要额外2 N向下作用平衡；上方绳不能提供向下拉力。'));
revise('p10-2',15,c(3,'物体空气中重5 N，全浸水中静止读3 N。取ρ水1000 kg/m³、g10 N/kg，物体不吸水且不触底壁，其平均密度为？',['1000 kg/m³','1500 kg/m³','2500 kg/m³','5000 kg/m³'],2,'质量m=5/10=0.5 kg；浮力2 N对应体积0.0002 m³；ρ物=0.5/0.0002=2500 kg/m³。'));
revise('p10-3',15,c(3,'漂浮小船载一块重20 N、体积500 cm³的金属，后把金属放入水中沉底。ρ水1000 kg/m³，g10 N/kg，忽略船自身变化与接触特殊效应，总排水体积怎样变化？',['增加1500 cm³','减少1500 cm³','不变','减少500 cm³'],1,'金属在船上使船多排水V=G/(ρg)=2000 cm³；放水后金属只排500 cm³，减少1500 cm³。'));
revise('p11-2',14,t(3,'提升机20 s内把200 kg货物匀速升5 m，同时消耗总输入功12500 J，g10 N/kg。求提升货物的有用功率多少W？只填数值。',['500'],'有用功=mgh=10000 J，除以20 s得500 W；输入功率625 W是另一个量，不能混用。'));
revise('p12-3',13,c(3,'同一滑轮组，两次匀速提升货重分别100 N和160 N，对应拉力分别60 N和90 N。忽略摩擦，动轮重不变。承重股数与动轮重为？',['2股、20 N','3股、80 N','2股、10 N','3股、20 N'],0,'联立n×60=100+G动、n×90=160+G动，相减得30n=60，n=2，再得G动=20 N。'));

