revise('p12-1',14,{...t(3,'如图，轻质水平杠杆左侧0.2 m处挂10 N，右侧0.1 m处挂5 N；再在右侧0.3 m处向下加力F使平衡，F为多少N？',['5'],'左力矩10×0.2=2 N·m，右已0.5 N·m，还需1.5 N·m；F=1.5/0.3=5 N。'),diagram:svg('q-p12-1-14','杠杆三力平衡示意',ln(90,140,610,140,'#7d987e',9)+`<path d="M300 148L282 185H318Z" fill="#c3d3ba" stroke="#658075"/>`+arr('q-p12-1-14',100,140,100,240,'#b05b39')+arr('q-p12-1-14',400,140,400,208)+arr('q-p12-1-14',600,140,600,228)+tx(67,270,'10 N')+tx(373,240,'5 N')+tx(592,259,'F')+tx(183,101,'0.2 m')+tx(332,101,'0.1 m')+tx(436,55,'0.3 m')+ln(300,68,600,68,'#607d70',2)+tx(288,213,'O'))});

const extraCore={
'p7-2':'把记录表中的总长先减原长，再作图，可以避免看似“线性”却没有经过正确原点的问题。测量应保留仪器允许的精度，不要凭空增加小数位。',
'p9-1':'同一块物体如果受到其他支撑，应先求真正传给这一接触面的压力。总重量与某一处压力之间的差别，正是组合问题中需要单独列受力关系的原因。',
'p9-3':'所有数值估算都要先说明采用的气压和重力常数。当地气压随天气也会变化，所以标准大气压是规定的参考值，不代表每个地点每一天完全相同。',
'p10-2':'读题时将液体密度、物体密度分别标成不同符号。求浮力先用液体密度，求物体质量与体积比时才使用物体密度，保持符号清楚能避免两种对象混用。',
'p11-1':'功的数值还应检查数量级，力用牛顿、距离用米时得到焦耳。厘米若忘记换成米，会让结果放大一百倍；把质量直接写作力，则还遗漏了重力与质量的转换。',
'p11-2':'额定功率是设备设计工作条件下的参数，实际工作时未必始终达到额定值。若题目给的是总输入功率而问有用输出功率，还需要效率信息，不能不加区分地直接等同。',
'p12-3':'图中同一根绳的不同段虽然张力相同，却可能分别作用于支架、滑轮和重物。只有向上作用在所选移动整体上的部分才算承重，不能把支架受力也算进去。',
'p12-4':'题目中的有用功要根据目标定义。如果任务是从井里取水，提升桶本身通常是额外功；若任务就是取出桶，则桶的提升又可以属于有用功，不能只按物体名称死记。'
};
